exceptions-validation.code:
def parse_port(raw):
    try:
        port = int(raw)
    except ValueError as error:
        raise ValueError("port must be an integer") from error
    if not 1 <= port <= 65535:
        raise ValueError("port must be 1-65535")
    return port

print(f"Port: {parse_port("8080")}")

