def safe_average(values):
    if not values:
        return 0
    return sum(values) / len(values)

assert safe_average([2, 4, 6]) == 4
assert safe_average([]) == 0
assert safe_average([10]) == 10
print("3 tests passed")

http-apis.code:
RESPONSE = {"status": 200, "json": {"name": " Ada ", "active": True}}

def normalize_user(response):
    if response.get("status") != 200:
        raise RuntimeError("request failed")
    body = response.get("json")
    if not isinstance(body, dict) or not isinstance(body.get("name"), str):
        raise ValueError("invalid user schema")
    return {"name": body["name"].strip().lower(), "active": body.get("active") is True}

user = normalize_user(RESPONSE)
print(f"User: {user["name"]} | Active: {user["active"]}")
